import pytest
from candidate import separate_paren_groups


class TestSeparateParenGroupsNormalCases:
    def test_single_simple_group(self):
        assert separate_paren_groups('()') == ['()']

    def test_single_nested_group(self):
        assert separate_paren_groups('(())') == ['(())']

    def test_two_simple_groups(self):
        assert separate_paren_groups('()()') == ['()', '()']

    def test_multiple_nested_groups(self):
        assert separate_paren_groups('(())(())') == ['(())', '(())']

    def test_deeply_nested_group(self):
        assert separate_paren_groups('((()))') == ['((()))']

    def test_deeply_nested_with_multiple_levels(self):
        assert separate_paren_groups('(((())))') == ['(((())))']

    def test_mixed_complex_nesting(self):
        assert separate_paren_groups('(()(()))') == ['(()(()))']

    def test_example_from_docstring(self):
        assert separate_paren_groups('( ) (( )) (( )( ))') == ['()', '(())', '(()())']

    def test_three_groups_with_nesting(self):
        assert separate_paren_groups('(())(())(())') == ['(())', '(()', '(())']

    def test_many_simple_groups(self):
        assert separate_paren_groups('()()()()()') == ['()', '()', '()', '()', '()']

    def test_single_char_nesting(self):
        assert separate_paren_groups('()()') == ['()', '()']


class TestSeparateParenGroupsSpaces:
    def test_spaces_between_groups(self):
        assert separate_paren_groups('() ()') == ['()', '()']

    def test_spaces_inside_group(self):
        assert separate_paren_groups('( )') == ['()']

    def test_spaces_everywhere(self):
        assert separate_paren_groups(' ( ) ( ( ) ) ') == ['()', '(())']

    def test_only_spaces(self):
        assert separate_paren_groups('   ') == []

    def test_tabs_and_spaces(self):
        assert separate_paren_groups('\t( )\t( )') == ['()', '()']

    def test_newlines_ignored(self):
        assert separate_paren_groups('( )\n( )') == ['()', '()']


class TestSeparateParenGroupsEdgeCases:
    def test_empty_string(self):
        assert separate_paren_groups('') == []

    def test_single_open_paren(self):
        assert separate_paren_groups('(') == []

    def test_single_close_paren(self):
        assert separate_paren_groups(')') == []

    def test_unbalanced_open_after_balanced(self):
        assert separate_paren_groups('()(') == ['()']

    def test_unbalanced_close_before_balanced(self):
        assert separate_paren_groups(')()') == ['()']

    def test_consecutive_unbalanced(self):
        assert separate_paren_groups('(()') == []

    def test_extra_close_parens(self):
        assert separate_paren_groups('())') == ['()']

    def test_very_deep_nesting(self):
        s = '(' * 50 + ')' * 50
        assert separate_paren_groups(s) == [s]

    def test_very_deep_nesting_multiple_groups(self):
        s1 = '(' * 20 + ')' * 20
        s2 = '(' * 10 + ')' * 10
        assert separate_paren_groups(s1 + s2) == [s1, s2]

    def test_no_spaces_in_output(self):
        result = separate_paren_groups(' ( ) ( ( ) ) ')
        for group in result:
            assert ' ' not in group


class TestSeparateParenGroupsReturnTypes:
    def test_returns_list(self):
        assert isinstance(separate_paren_groups('()'), list)

    def test_returns_list_of_strings(self):
        result = separate_paren_groups('()()')
        assert all(isinstance(item, str) for item in result)

    def test_returns_empty_list_for_empty_input(self):
        result = separate_paren_groups('')
        assert isinstance(result, list)
        assert len(result) == 0


class TestSeparateParenGroupsErrorHandling:
    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            separate_paren_groups(None)

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            separate_paren_groups(123)

    def test_float_input_raises_type_error(self):
        with pytest.raises(TypeError):
            separate_paren_groups(3.14)

    def test_list_input_raises_type_error(self):
        with pytest.raises(TypeError):
            separate_paren_groups(['(', ')'])

    def test_dict_input_raises_type_error(self):
        with pytest.raises(TypeError):
            separate_paren_groups({'a': 1})


class TestSeparateParenGroupsIndependence:
    def test_result_independent_of_call_order(self):
        r1 = separate_paren_groups('()()')
        r2 = separate_paren_groups('(())')
        assert r1 == ['()', '()']
        assert r2 == ['(())']

    def test_repeated_calls_same_result(self):
        for _ in range(3):
            assert separate_paren_groups('()()(())') == ['()', '()', '(())']

    def test_input_string_not_modified(self):
        s = '( ) (( ))'
        original = s
        separate_paren_groups(s)
        assert s == original
